    private static Decision unmeasured(int cores){return new Decision(baseline(cores),false,false,0,0,0,"unmeasured");}

    /** All shortlisted configurations need complete alternating trials before a decision is cacheable. */
    static Decision select(Key key,Candidate[] trials){
