    }
    private static void validateDecision(Decision d,Key key)throws IOException{
        if(d==null||!d.complete||d.pairCount<MIN_PAIRS||d.pairCount>MAX_PAIRS||d.baselineMedianNanos<=0||d.candidateMedianNanos<=0||d.baselineMedianNanos>MAX_TRIAL_NANOS||d.candidateMedianNanos>MAX_TRIAL_NANOS)
